// ======================= CONFIG — EDIT ME =======================
const CONFIG = {
  GHL_TOKEN: 'pit-REPLACE_WITH_PRIVATE_INTEGRATION_TOKEN', // GHL > Settings > Private Integrations
  LOCATION_ID: 'REPLACE_WITH_LOCATION_ID',
  // GHL custom field IDs (create them as Single Line TEXT fields)
  FIELD_IDS: {
    confirmationSent: 'REPLACE_webinar_confirmation_sent', // "yes" once confirmation is sent
    sequenceStep:     'REPLACE_webinar_sequence_step',     // number of follow-ups already sent
    nextSendAt:       'REPLACE_webinar_next_send_at',      // ISO date of next follow-up
    lastSentAt:       'REPLACE_webinar_last_sent_at',      // ISO date of last email sent
  },
  REGISTERED_TAG: 'webinar-registered',
};
const GHL = 'https://services.leadconnectorhq.com';
const ghlHeaders = {
  Authorization: `Bearer ${CONFIG.GHL_TOKEN}`,
  Version: '2021-07-28',
  Accept: 'application/json',
  'Content-Type': 'application/json',
};
// ================================================================

const STOP_TAGS = ['unsubscribed', 'do-not-email', 'webinar-sequence-complete', 'webinar-sequence-failed'];
const MAX_PER_RUN = 40;   // keeps you well under Gmail sending limits
const HOST = 'Nike';
const LINKS = {
  replay: 'https://your-replay-link.com',
  booking: 'https://your-booking-link.com',
  resource: 'https://your-resource-link.com',
};

const wrap = (inner) => `<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto;color:#222;line-height:1.6">${inner}<p>— ${HOST}</p><p style="font-size:12px;color:#888">Reply "stop" and I won't email you about this again.</p></div>`;
const btn = (href, label) => `<p style="margin:22px 0"><a href="${href}" style="background:#ff6d2d;color:#fff;padding:12px 22px;border-radius:6px;text-decoration:none;font-weight:bold">${label}</a></p>`;

// Each step: email content + hours to wait AFTER sending it before the next step.
// Step 1 fires FIRST_FOLLOWUP_DELAY_HOURS after the confirmation (set in the Confirmation workflow).
const SEQUENCE = [
  {
    subject: (n) => `${n}, a quick resource before we go live`,
    html: (n) => wrap(`<p>Hi ${n},</p><p>To get the most out of the webinar, have a look at this short resource beforehand.</p>${btn(LINKS.resource, 'Get the resource')}`),
    waitAfterHours: 48,
  },
  {
    subject: (n) => `The replay + key takeaways`,
    html: (n) => wrap(`<p>Hi ${n},</p><p>Whether you made it live or not, here's the full replay and the key takeaways.</p>${btn(LINKS.replay, 'Watch the replay')}`),
    waitAfterHours: 72,
  },
  {
    subject: (n) => `Want help putting this into action, ${n}?`,
    html: (n) => wrap(`<p>Hi ${n},</p><p>If you'd like help applying what we covered to your business, grab a free call slot below.</p>${btn(LINKS.booking, 'Book a call')}`),
    waitAfterHours: 0,
  },
];

// ---- Fetch tagged contacts from GHL (paginated) ----
let contacts = [];
for (let page = 1; page <= 10; page++) {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${GHL}/contacts/search`,
    headers: ghlHeaders,
    body: {
      locationId: CONFIG.LOCATION_ID,
      page,
      pageLimit: 100,
      filters: [{ field: 'tags', operator: 'contains', value: CONFIG.REGISTERED_TAG }],
    },
    json: true,
  });
  const batch = res.contacts || [];
  contacts.push(...batch);
  if (batch.length < 100) break;
}

const sd = $getWorkflowStaticData('global');
sd.sent = sd.sent || {};
const now = Date.now();
const field = (c, id) => (c.customFields || []).find(f => f.id === id)?.value;

const leads = [];
for (const c of contacts) {
  const tags = (c.tags || []).map(t => String(t).toLowerCase());
  if (!tags.includes(CONFIG.REGISTERED_TAG)) continue;          // safety net if filter is ignored
  if (STOP_TAGS.some(t => tags.includes(t))) continue;
  if (c.dnd) continue;

  const email = (c.email || '').toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) continue;

  const step = parseInt(field(c, CONFIG.FIELD_IDS.sequenceStep) ?? '', 10);
  const nextSendAt = field(c, CONFIG.FIELD_IDS.nextSendAt);
  if (Number.isNaN(step) || !nextSendAt) continue;               // not enrolled yet
  if (step >= SEQUENCE.length) continue;                          // finished
  if (new Date(nextSendAt).getTime() > now) continue;             // not due yet
  if (sd.sent[`${c.id}:${step}`]) continue;                       // already sent this step

  const s = SEQUENCE[step];
  const name = c.firstName || 'there';
  const isLastStep = step === SEQUENCE.length - 1;

  leads.push({
    hasLeads: true,
    contactId: c.id,
    email,
    firstName: c.firstName || '',
    step,
    stepNumber: step + 1,
    subject: s.subject(name),
    html: s.html(name),
    isLastStep,
    nextSendAtAfterSend: isLastStep ? '' : new Date(now + s.waitAfterHours * 3600e3).toISOString(),
  });
  if (leads.length >= MAX_PER_RUN) break;
}

if (!leads.length) return [{ json: { hasLeads: false, checked: contacts.length } }];
return leads.map(l => ({ json: l }));

// ======================= CONFIG — EDIT ME =======================
const CONFIG = {
  GHL_TOKEN: 'pit-REPLACE_WITH_PRIVATE_INTEGRATION_TOKEN', // GHL > Settings > Private Integrations
  LOCATION_ID: 'REPLACE_WITH_LOCATION_ID',
  // GHL custom field IDs (create them as Single Line TEXT fields)
  FIELD_IDS: {
    confirmationSent: 'REPLACE_webinar_confirmation_sent', // "yes" once confirmation is sent
    sequenceStep:     'REPLACE_webinar_sequence_step',     // number of follow-ups already sent
    nextSendAt:       'REPLACE_webinar_next_send_at',      // ISO date of next follow-up
    lastSentAt:       'REPLACE_webinar_last_sent_at',      // ISO date of last email sent
  },
  REGISTERED_TAG: 'webinar-registered',
};
const GHL = 'https://services.leadconnectorhq.com';
const ghlHeaders = {
  Authorization: `Bearer ${CONFIG.GHL_TOKEN}`,
  Version: '2021-07-28',
  Accept: 'application/json',
  'Content-Type': 'application/json',
};
// ================================================================

const COMPLETE_TAG = 'webinar-sequence-complete';
const FAILED_TAG = 'webinar-sequence-failed';
const MAX_FAILURES = 3;

const sd = $getWorkflowStaticData('global');
sd.sent = sd.sent || {};
sd.failures = sd.failures || {};
const nowIso = new Date().toISOString();

// prune sent log older than 60 days
for (const [k, ts] of Object.entries(sd.sent)) {
  if (Date.now() - new Date(ts).getTime() > 60 * 24 * 3600e3) delete sd.sent[k];
}

const addTag = (id, tag) => this.helpers.httpRequest({
  method: 'POST', url: `${GHL}/contacts/${id}/tags`, headers: ghlHeaders, body: { tags: [tag] }, json: true,
});

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const g = items[i].json;
  let lead;
  try { lead = $('Build Send List').itemMatching(i).json; }
  catch { lead = $('Build Send List').all()[i].json; }

  const key = `${lead.contactId}:${lead.step}`;

  // Gmail failed for this lead → leave fields untouched so it retries next run
  if (g.error) {
    sd.failures[lead.contactId] = (sd.failures[lead.contactId] || 0) + 1;
    let tagged = false;
    if (sd.failures[lead.contactId] >= MAX_FAILURES) {
      try { await addTag(lead.contactId, FAILED_TAG); tagged = true; } catch {}
    }
    out.push({ json: { contactId: lead.contactId, email: lead.email, step: lead.stepNumber,
      status: 'send_failed', failures: sd.failures[lead.contactId], taggedFailed: tagged,
      error: String(g.error?.message ?? g.error) } });
    continue;
  }

  sd.sent[key] = nowIso;
  delete sd.failures[lead.contactId];

  let ghlUpdated = false, ghlError = null;
  try {
    await this.helpers.httpRequest({
      method: 'PUT',
      url: `${GHL}/contacts/${lead.contactId}`,
      headers: ghlHeaders,
      body: {
        customFields: [
          { id: CONFIG.FIELD_IDS.sequenceStep, field_value: String(lead.step + 1) },
          { id: CONFIG.FIELD_IDS.lastSentAt, field_value: nowIso },
          { id: CONFIG.FIELD_IDS.nextSendAt, field_value: lead.nextSendAtAfterSend },
        ],
      },
      json: true,
    });
    if (lead.isLastStep) await addTag(lead.contactId, COMPLETE_TAG);
    ghlUpdated = true;
  } catch (e) {
    ghlError = e.message;
  }

  out.push({ json: { contactId: lead.contactId, email: lead.email, step: lead.stepNumber,
    status: 'sent', messageId: g.id || null, completed: lead.isLastStep, ghlUpdated, ghlError } });
}

return out;
